// The harness entry points are generated by the benchmark framework and carry
// no documentation of their own.
#![allow(missing_docs)]

//! Decode throughput.
//!
//! Every stage after this one decodes the whole image, so this number is the
//! floor on what any analysis pass can cost. It exists to give later changes a
//! baseline to regress against, not to be optimized for its own sake.
//!
//! Set `XENOLITH_BENCH_IMAGE` to a decoded image to measure against real code
//! rather than a synthetic stream. Real code has a very different instruction
//! mix from evenly spread words, and the dispatch is a two level match whose
//! cost depends on which arms are taken.

use std::hint::black_box;

use criterion::{Criterion, Throughput, criterion_group, criterion_main};
use xenolith_ppc::Instruction;

/// Builds a stream of words spread evenly across the encoding space.
fn synthetic_stream(count: usize) -> Vec<u32> {
    let mut state = 0x2545_f491u32;
    (0..count)
        .map(|_| {
            state = state.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
            state
        })
        .collect()
}

/// Loads real instruction words, if an image was supplied.
fn real_stream() -> Option<Vec<u32>> {
    let path = std::env::var_os("XENOLITH_BENCH_IMAGE")?;
    let bytes = std::fs::read(path).ok()?;

    Some(
        bytes
            .chunks_exact(4)
            .filter_map(|chunk| <[u8; 4]>::try_from(chunk).ok())
            .map(u32::from_be_bytes)
            .take(1 << 20)
            .collect(),
    )
}

fn decode_only(words: &[u32]) -> usize {
    words
        .iter()
        .filter(|word| !Instruction::decode(**word).is_unknown())
        .count()
}

fn decode_and_classify(words: &[u32]) -> usize {
    words
        .iter()
        .enumerate()
        .filter(|(index, word)| {
            let offset = u32::try_from(*index).unwrap_or(0).wrapping_mul(4);
            let address = 0x8200_0000u32.wrapping_add(offset);
            Instruction::decode(**word).flow(address).terminates_block()
        })
        .count()
}

fn benchmarks(c: &mut Criterion) {
    let synthetic = synthetic_stream(1 << 20);

    let mut group = c.benchmark_group("synthetic");
    group.throughput(Throughput::Elements(synthetic.len() as u64));
    group.bench_function("decode", |b| {
        b.iter(|| black_box(decode_only(black_box(&synthetic))));
    });
    group.bench_function("decode_and_classify", |b| {
        b.iter(|| black_box(decode_and_classify(black_box(&synthetic))));
    });
    group.finish();

    let Some(real) = real_stream() else {
        eprintln!("skipping the real code benchmark: XENOLITH_BENCH_IMAGE is not set");
        return;
    };

    let mut group = c.benchmark_group("real_code");
    group.throughput(Throughput::Elements(real.len() as u64));
    group.bench_function("decode", |b| {
        b.iter(|| black_box(decode_only(black_box(&real))));
    });
    group.finish();
}

criterion_group!(benches, benchmarks);
criterion_main!(benches);
